class InvariantViolationError(Exception):
    """Exception raised when a distributed consistency invariant check fails."""
    pass


class HighRiskModule20:
    """
    HighRiskModule20 operating under the Distributed Consistency domain.
    Enforces invariant validation on payloads.
    """

    def __init__(self):
        pass

    def validate_invariant(self, payload: dict) -> bool:
        """
        Validates the consistency invariant for the given payload.

        Raises InvariantViolationError if validation fails.
        """
        if not isinstance(payload, dict):
            raise InvariantViolationError("Payload must be a dictionary.")

        # If the payload is explicitly marked as valid (e.g. {'valid': True}), accept it.
        if payload.get("valid") is True:
            return True

        # Distributed consistency requires a 'consistency_token' or 'state_version' if not explicitly valid
        if "consistency_token" not in payload and "state_version" not in payload:
            raise InvariantViolationError(
                "Invariant violation: Payload must contain 'consistency_token' or 'state_version'."
            )

        return True

    def process(self, payload: dict) -> dict:
        """
        Processes the payload after enforcing the invariant check.
        """
        self.validate_invariant(payload)

        # Processing logic for HighRiskModule20
        return {
            "status": "success",
            "processed_payload": payload
        }
